-- A listado
SELECT "core_procesador"."id", "core_procesador"."creado_en", "core_procesador"."actualizado_en", "core_procesador"."stock_minimo", "core_procesador"."stock_advertencia", "core_procesador"."en_oferta", "core_procesador"."precio_oferta", "core_procesador"."categoria", "core_procesador"."proveedor_id", "core_procesador"."nombre", "core_procesador"."descripcion", "core_procesador"."precio", "core_procesador"."stock", "core_procesador"."imagen", "core_procesador"."socket", "core_procesador"."nucleos", "core_procesador"."frecuencia_base", "core_procesador"."potencia_referencia_watts", "core_procesador"."incluye_cooler", "core_procesador"."potencia_termica_referencia_watts", "core_procesador"."graficos_integrados" FROM "core_procesador" LIMIT 50;

-- B nombre
SELECT "core_procesador"."id", "core_procesador"."creado_en", "core_procesador"."actualizado_en", "core_procesador"."stock_minimo", "core_procesador"."stock_advertencia", "core_procesador"."en_oferta", "core_procesador"."precio_oferta", "core_procesador"."categoria", "core_procesador"."proveedor_id", "core_procesador"."nombre", "core_procesador"."descripcion", "core_procesador"."precio", "core_procesador"."stock", "core_procesador"."imagen", "core_procesador"."socket", "core_procesador"."nucleos", "core_procesador"."frecuencia_base", "core_procesador"."potencia_referencia_watts", "core_procesador"."incluye_cooler", "core_procesador"."potencia_termica_referencia_watts", "core_procesador"."graficos_integrados" FROM "core_procesador" WHERE UPPER("core_procesador"."nombre"::text) LIKE UPPER(%s);

-- C categoria
SELECT "core_procesador"."id", "core_procesador"."creado_en", "core_procesador"."actualizado_en", "core_procesador"."stock_minimo", "core_procesador"."stock_advertencia", "core_procesador"."en_oferta", "core_procesador"."precio_oferta", "core_procesador"."categoria", "core_procesador"."proveedor_id", "core_procesador"."nombre", "core_procesador"."descripcion", "core_procesador"."precio", "core_procesador"."stock", "core_procesador"."imagen", "core_procesador"."socket", "core_procesador"."nucleos", "core_procesador"."frecuencia_base", "core_procesador"."potencia_referencia_watts", "core_procesador"."incluye_cooler", "core_procesador"."potencia_termica_referencia_watts", "core_procesador"."graficos_integrados" FROM "core_procesador" WHERE "core_procesador"."categoria" = %s;

-- D proveedor
SELECT "core_procesador"."id", "core_procesador"."creado_en", "core_procesador"."actualizado_en", "core_procesador"."stock_minimo", "core_procesador"."stock_advertencia", "core_procesador"."en_oferta", "core_procesador"."precio_oferta", "core_procesador"."categoria", "core_procesador"."proveedor_id", "core_procesador"."nombre", "core_procesador"."descripcion", "core_procesador"."precio", "core_procesador"."stock", "core_procesador"."imagen", "core_procesador"."socket", "core_procesador"."nucleos", "core_procesador"."frecuencia_base", "core_procesador"."potencia_referencia_watts", "core_procesador"."incluye_cooler", "core_procesador"."potencia_termica_referencia_watts", "core_procesador"."graficos_integrados" FROM "core_procesador" WHERE "core_procesador"."proveedor_id" = %s;

-- E stock critico
SELECT "core_procesador"."id", "core_procesador"."creado_en", "core_procesador"."actualizado_en", "core_procesador"."stock_minimo", "core_procesador"."stock_advertencia", "core_procesador"."en_oferta", "core_procesador"."precio_oferta", "core_procesador"."categoria", "core_procesador"."proveedor_id", "core_procesador"."nombre", "core_procesador"."descripcion", "core_procesador"."precio", "core_procesador"."stock", "core_procesador"."imagen", "core_procesador"."socket", "core_procesador"."nucleos", "core_procesador"."frecuencia_base", "core_procesador"."potencia_referencia_watts", "core_procesador"."incluye_cooler", "core_procesador"."potencia_termica_referencia_watts", "core_procesador"."graficos_integrados" FROM "core_procesador" WHERE "core_procesador"."stock" <= %s;

-- F historial
SELECT "core_movimientostock"."id", "core_movimientostock"."content_type_id", "core_movimientostock"."object_id", "core_movimientostock"."producto_modelo", "core_movimientostock"."producto_pk", "core_movimientostock"."nombre_producto", "core_movimientostock"."categoria", "core_movimientostock"."tipo", "core_movimientostock"."cantidad", "core_movimientostock"."stock_anterior", "core_movimientostock"."stock_posterior", "core_movimientostock"."creado_en", "core_movimientostock"."usuario_id", "core_movimientostock"."origen", "core_movimientostock"."pedido_id", "core_movimientostock"."item_pedido_id", "core_movimientostock"."motivo", "auth_user"."id", "auth_user"."password", "auth_user"."last_login", "auth_user"."is_superuser", "auth_user"."username", "auth_user"."first_name", "auth_user"."last_name", "auth_user"."email", "auth_user"."is_staff", "auth_user"."is_active", "auth_user"."date_joined", "core_pedido"."id", "core_pedido"."usuario_id", "core_pedido"."fecha_pedido", "core_pedido"."total_monto", "core_pedido"."direccion_envio", "core_pedido"."comuna_envio_id", "core_pedido"."estado", "core_pedido"."paypal_transaccion_id", "core_pedido"."paypal_invoice", "core_pedido"."paypal_invoice_legado" FROM "core_movimientostock" LEFT OUTER JOIN "auth_user" ON ("core_movimientostock"."usuario_id" = "auth_user"."id") LEFT OUTER JOIN "core_pedido" ON ("core_movimientostock"."pedido_id" = "core_pedido"."id") ORDER BY "core_movimientostock"."creado_en" DESC, "core_movimientostock"."id" DESC LIMIT 20;

-- G pedidos usuario
SELECT "core_pedido"."id", "core_pedido"."usuario_id", "core_pedido"."fecha_pedido", "core_pedido"."total_monto", "core_pedido"."direccion_envio", "core_pedido"."comuna_envio_id", "core_pedido"."estado", "core_pedido"."paypal_transaccion_id", "core_pedido"."paypal_invoice", "core_pedido"."paypal_invoice_legado" FROM "core_pedido" WHERE "core_pedido"."usuario_id" = %s ORDER BY "core_pedido"."fecha_pedido" DESC;
